  @Test
  void initWithBuildsAWorkingPipeline() {
    InMemorySpanExporter exporter = new InMemorySpanExporter();
    TracingHandle h =
        Tracing.initWith(
            config()
                .serviceVersion("1.0.0")
                .environment("test")
                .resourceAttributes(Map.of("team", "core", "replicas", 2))
                .build(),
            c -> exporter);
    try {
      assertThat(Tracing.openTelemetry()).isSameAs(h.openTelemetry());
      h.tracer("t").spanBuilder("one").startSpan().end();
      h.tracer("t", "1.0").spanBuilder("two").startSpan().end();
      h.forceFlush();
      h.forceFlush(Duration.ofSeconds(5));
      h.forceFlushAsync(Duration.ofSeconds(5)).join();
      List<SpanData> spans = exporter.spans();
      assertThat(spans).extracting(SpanData::getName).containsExactly("one", "two");
      Resource r = spans.get(0).getResource();
      assertThat(r.getAttribute(AttributeKey.stringKey("service.name"))).isEqualTo("svc");
      assertThat(r.getAttribute(AttributeKey.stringKey("service.version"))).isEqualTo("1.0.0");
      assertThat(r.getAttribute(AttributeKey.stringKey("deployment.environment")))
          .isEqualTo("test");
      assertThat(r.getAttribute(AttributeKey.longKey("replicas"))).isEqualTo(2L);
      assertThat(h.config().serviceName()).isEqualTo("svc");
      assertThat(h.propagators().getTextMapPropagator().fields())
          .contains("traceparent", "baggage");
      assertThat(h.tracerProvider()).isNotNull();
      assertThat(h.isShutdown()).isFalse();
    } finally {
      h.shutdown();
    }
    assertThat(h.isShutdown()).isTrue();
    h.close();
    h.shutdownAsync().join();
    assertThat(exporter.isShutdown()).isTrue();
    assertThat(Tracing.openTelemetry()).isNotSameAs(h.openTelemetry());
  }

