  @Test
  void forceFlushFailureIsATimeout() {
    SpanExporter stuck =
        new SpanExporter() {
          @Override
          public CompletableResultCode export(Collection<SpanData> spans) {
            return new CompletableResultCode();
          }

          @Override
          public CompletableResultCode flush() {
            return new CompletableResultCode();
          }

          @Override
          public CompletableResultCode shutdown() {
            return new CompletableResultCode();
          }
        };
    TracingHandle h =
        Tracing.initWith(
            config()
                .batch(
                    new TracingConfig.BatchSettings(
                        10, 5, Duration.ofSeconds(5), Duration.ofMillis(100)))
                .build(),
            c -> stuck);
    h.tracer("t").spanBuilder("s").startSpan().end();
    assertThatThrownBy(() -> h.forceFlush(Duration.ofMillis(100)))
        .isInstanceOf(TimeoutException.class);
    assertThatThrownBy(h::shutdown).isInstanceOf(TimeoutException.class);
  }

