  @Test
  void otelAttributes() {
    Attributes a =
        OtelAttributes.from(
            new java.util.LinkedHashMap<String, Object>() {
              private static final long serialVersionUID = 1L;

              {
                put("s", "v");
                put("b", true);
                put("i", 1);
                put("l", 2L);
                put("sh", (short) 3);
                put("by", (byte) 4);
                put("d", 1.5);
                put("f", 2.5f);
                put("m", Map.of("x", Map.of("y", 1)));
                put("ls", List.of("a", "b"));
                put("lb", List.of(true));
                put("ll", List.of(1, 2L));
                put("ld", List.of(1, 2.5));
                put("lm", List.of("a", 1));
                put("le", List.of());
                put("o", java.time.Duration.ofSeconds(1));
                put("n", null);
              }
            });
    assertThat(a.get(AttributeKey.stringKey("s"))).isEqualTo("v");
    assertThat(a.get(AttributeKey.booleanKey("b"))).isTrue();
    assertThat(a.get(AttributeKey.longKey("i"))).isEqualTo(1L);
    assertThat(a.get(AttributeKey.longKey("sh"))).isEqualTo(3L);
    assertThat(a.get(AttributeKey.longKey("by"))).isEqualTo(4L);
    assertThat(a.get(AttributeKey.doubleKey("f"))).isEqualTo(2.5);
    assertThat(a.get(AttributeKey.longKey("m.x.y"))).isEqualTo(1L);
    assertThat(a.get(AttributeKey.stringArrayKey("ls"))).containsExactly("a", "b");
    assertThat(a.get(AttributeKey.booleanArrayKey("lb"))).containsExactly(true);
    assertThat(a.get(AttributeKey.longArrayKey("ll"))).containsExactly(1L, 2L);
    assertThat(a.get(AttributeKey.doubleArrayKey("ld"))).containsExactly(1.0, 2.5);
    assertThat(a.get(AttributeKey.stringArrayKey("lm"))).containsExactly("a", "1");
    assertThat(a.get(AttributeKey.stringArrayKey("le"))).isEmpty();
    assertThat(a.get(AttributeKey.stringKey("o"))).isEqualTo("PT1S");
    assertThat(a.get(AttributeKey.stringKey("n"))).isNull();
    assertThat(OtelAttributes.from(null).isEmpty()).isTrue();
  }

  @Test
  void otlpExporters(@TempDir Path dir) throws Exception {
    assertThat(OtlpExporters.httpEndpoint(config().build()))
        .isEqualTo(OtlpExporters.DEFAULT_HTTP_ENDPOINT);
    assertThat(OtlpExporters.httpEndpoint(config().endpoint("http://c:4318").build()))
        .isEqualTo("http://c:4318/v1/traces");
    assertThat(OtlpExporters.httpEndpoint(config().endpoint("http://c:4318/").build()))
        .isEqualTo("http://c:4318/v1/traces");
    assertThat(OtlpExporters.httpEndpoint(config().endpoint("http://c/custom").build()))
        .isEqualTo("http://c/custom");
    SpanExporter http =
        OtlpExporters.factory()
            .create(
                config().header("x-api", "k").compression(TracingConfig.Compression.NONE).build());
    assertThat(http.getClass().getSimpleName()).isEqualTo("OtlpHttpSpanExporter");
    http.shutdown();
    SpanExporter grpc =
        OtlpExporters.create(
            config().protocol(TracingConfig.Protocol.GRPC).header("x-api", "k").build());
    assertThat(grpc.getClass().getSimpleName()).isEqualTo("OtlpGrpcSpanExporter");
    grpc.shutdown();
    assertThatThrownBy(
            () -> OtlpExporters.create(config().protocol(TracingConfig.Protocol.NATIVE).build()))
        .isInstanceOf(ConfigException.class);

    // TLS: insecure works without files; plain defaults are ignored
    TlsOptions insecure = TlsOptions.builder().insecureSkipVerify(true).build();
    OtlpExporters.create(config().tls(insecure).build()).shutdown();
    OtlpExporters.create(
            config().protocol(TracingConfig.Protocol.GRPC).tls(TlsOptions.defaults()).build())
        .shutdown();
    // unreadable files are configuration errors
    TlsOptions missingCa = TlsOptions.builder().caCertPath(dir.resolve("nope.pem")).build();
    assertThatThrownBy(() -> OtlpExporters.create(config().tls(missingCa).build()))
        .isInstanceOf(ConfigException.class);
    Path cert = Files.writeString(dir.resolve("c.pem"), "not a cert");
    TlsOptions missingKey =
        TlsOptions.builder().clientCertPath(cert).clientKeyPath(dir.resolve("k.pem")).build();
    assertThatThrownBy(() -> OtlpExporters.create(config().tls(missingKey).build()))
        .isInstanceOf(ConfigException.class);
    // invalid PEM material is rejected by the exporter builder
    TlsOptions badPem =
        TlsOptions.builder()
            .caCertPem("-----BEGIN CERTIFICATE-----\nAAAA\n-----END CERTIFICATE-----\n")
            .build();
    assertThatThrownBy(() -> OtlpExporters.create(config().tls(badPem).build()))
        .isInstanceOf(RuntimeException.class);
    Path key = Files.writeString(dir.resolve("k.pem"), "not a key");
    TlsOptions badClient =
        TlsOptions.builder().caCertPath(cert).clientCertPath(cert).clientKeyPath(key).build();
    assertThatThrownBy(() -> OtlpExporters.create(config().tls(badClient).build()))
        .isInstanceOf(RuntimeException.class);
  }
